  from_num_tokens: Decimal;
  /** The currency that reached its owner: on a redemption the investor's payout currency (the user leg), on an invest tokenCurrency. A row without conversion has... */
  to_currency: string;
  /** The tokens of toCurrency that reached their owner: on a redemption what the investor received (the user leg), on an invest numTokens. 0 on a burn, and on a... */
  to_num_tokens: Decimal;
