/** OrderStateFeed. */
export interface OrderStateFeed {
  /** A unique 128-bit identifier for the order, deterministically generated within the GRVT backend */
  order_id: string;
  /** A unique identifier for the active order within a subaccount, specified by the client */
  client_order_id: string;
  /** The order state object being created or updated */
  order_state: OrderState;
}

/** OrderbookLevel. */
export interface OrderbookLevel {
  /** The price of the level. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  price: Decimal;
  /** The number of assets offered. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  size: Decimal;
  /** The number of open orders at this level */
  num_orders: number;
}

/** OrderbookLevels. */
export interface OrderbookLevels {
  /** Time at which the event was emitted in unix nanoseconds */
  event_time: Timestamp;
  /** The readable instrument name: Perpetual: `ETH_USDT_Perp` Future: `BTC_USDT_Fut_20Oct23` Call: `ETH_USDT_Call_20Oct23_2800` Put: `ETH_USDT_Put_20Oct23_2800` */
  instrument: string;
  /** The list of best bids up till query depth */
  bids: OrderbookLevel[] | null;
  /** The list of best asks up till query depth */
  asks: OrderbookLevel[] | null;
}

/** Positions. */
export interface Positions {
  /** Time at which the event was emitted in unix nanoseconds */
  event_time: Timestamp;
  /** The sub account ID that participated in the trade */
  sub_account_id: string;
  /** The instrument being represented */
  instrument: string;
  /** The size of the position. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. Negative for short positions */
  size: Decimal;
  /** The notional value of the position, negative for short assets, in the quote asset. Decimal string, e.g. "12.5". */
  notional: Decimal;
  /** The entry price of the position. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  entry_price: Decimal;
  /** The exit price of the position. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  exit_price: Decimal;
  /** The mark price of the position. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  mark_price: Decimal;
  /** The unrealized PnL of the position, in the quote asset. Decimal string, e.g. "12.5". */
  unrealized_pnl: Decimal;
  /** The realized PnL of the position, in the quote asset. Decimal string, e.g. "12.5". */
  realized_pnl: Decimal;
  /** The total PnL of the position, in the quote asset. Decimal string, e.g. "12.5". */
  total_pnl: Decimal;
  /** The ROI of the position, expressed as a percentage */
  roi: Decimal;
  /** The index price of the quote currency. (reported in `USD`) */
  quote_index_price: Decimal;
  /** The estimated liquidation price */
  est_liquidation_price: Decimal;
  /** The current leverage value for this position */
  leverage: Decimal;
  /** The cumulative fee paid on the position, in the quote asset. Decimal string, e.g. "12.5". */
  cumulative_fee: Decimal;
  /** The cumulative realized funding payment of the position, in the quote asset. Decimal string, e.g. "12.5". Positive if paid, negative if received */
  cumulative_realized_funding_payment: Decimal;
  /** The margin type of the position */
  margin_type: e.PositionMarginType;
  /** [IsolatedOnly] The wallet balance reserved for this isolated margin position, in the quote asset. Decimal string, e.g. "12.5". If this positions is liquidated... */
  isolated_balance?: Decimal;
  /** [IsolatedOnly] The initial margin of the isolated margin position, in the quote asset. Decimal string, e.g. "12.5". The `total_equity` required to open more... */
  isolated_im?: Decimal;
  /** [IsolatedOnly] The maintenance margin of the isolated margin position, in the quote asset. Decimal string, e.g. "12.5". The `total_equity` required to avoid... */
  isolated_mm?: Decimal;
}

/** Vault redemption queue section hidden from main view. All requests here have yet to age past the vault's minimum redemption period. */
export interface PreMinRedemptions {
  /** Pre-minimum-age redemption requests, ordered by age (first element is the oldest request that is pre-minimum-age). */
  requests: VaultRedemptionRequest[] | null;
  /** Number of shares in the pre-minimum-age section of the vault's redemption queue. */
  token_count: Decimal;
}

/** A Request for Quote (RFQ) lets a taker solicit private quotes on a single instrument from makers. */
export interface Rfq {
  /** Set by the server. A unique 128-bit identifier for the RFQ, deterministically generated within the GRVT backend */
  rfq_id: string;
  /** The subaccount initiating the RFQ */
  sub_account_id: string;
  /** RFQ TTL. The timestamp after which Gravity expires the RFQ, expressed in unix nanoseconds. Default 60s, cap 300s (per-instrument config) */
  expiry: Timestamp;
  /** The instrument to trade. Must be kind = STABLE_PERP */
  instrument: string;
  /** Requested size (positive). Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  size: Decimal;
  /** Optional — omitted = two-way request. The GRVT UI always fills it; API takers may withhold direction and accept two-way quotes */
  side?: e.RfqSide;
}

/** RfqQuoteFeed. */
export interface RfqQuoteFeed {
  /** The RFQ this estimate belongs to. A feed with no levels means the RFQ ended */
  rfq_id: string;
  /** Average fill price to sell the RFQ size. Decimal string, e.g. "65000.5"; up to 9 decimals. Omitted when the bid side is empty */
  best_bid?: Decimal;
  /** Average fill price to buy the RFQ size. Decimal string, e.g. "65000.5"; up to 9 decimals. Omitted when the ask side is empty */
  best_ask?: Decimal;
  /** The sell-side estimate (at most one level), from the bids */
  bid_levels: RfqQuoteLevel[] | null;
  /** The buy-side estimate (at most one level), from the asks */
  ask_levels: RfqQuoteLevel[] | null;
}

/** RfqQuoteLevel. */
export interface RfqQuoteLevel {
  /** Average fill price for the size. Decimal string, e.g. "65000.5"; up to 9 decimals. Rounded against the taker: up for asks, down for bids */
  price: Decimal;
  /** Fillable size, up to the RFQ size. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  size: Decimal;
  /** The maker's derived anonymous account id shown to the taker. Real maker identity is never exposed */
  maker_anon_account_id: string;
  /** Distinguishes an AON level (liftable only in full — POST-MVP) from a GTT level */
  time_in_force: e.TimeInForce;
}

/** RiskBracket. */
export interface RiskBracket {
  /** 1-indexed tier number */
  tier: number;
  /** Lower bound of notional value (inclusive) in quote currency */
  notional_floor: Decimal;
  /** Upper bound of notional value (exclusive) in quote currency, omitted for last tier */
  notional_cap?: Decimal;
  /** Maintenance margin rate as a decimal (e.g., '0.01' for 1%) */
  maintenance_margin_rate: Decimal;
  /** Initial margin rate as a decimal (e.g., '0.02' for 2%) */
  initial_margin_rate: Decimal;
  /** Maximum leverage allowed at this tier (floor of 1 / initial_margin_rate) */
  max_leverage: number;
  /** Cumulative maintenance margin amount in quote currency */
  cumulative_maintenance_amount: Decimal;
}

/** SfpMarketSchedule. */
export interface SfpMarketSchedule {
  /** Trading sessions for the current calendar week (Sunday to Saturday in the exchange's local time). The sessions are contiguous with no gaps, and any period when... */
  sessions: TradingSession[] | null;
  /** Market holidays and early closes, past and upcoming, sorted by start time. The market is closed from the start time to the end time of each entry. Empty when... */
  holidays: TradingHolidaySchedule[] | null;
}

/** SfpTradingScheduleGroup. */
export interface SfpTradingScheduleGroup {
  /** The group name. For stable perps on their asset class hours, the asset class (for example `COMMODITY_CME`) */
  name: string;
  /** The instruments' asset class. Its holiday calendar sets the group's holidays */
  asset_class: e.AssetClass;
  /** The stable perps trading these hours, sorted. Each stable perp with a schedule is in exactly one group */
  instruments: string[] | null;
  /** Trading sessions for the current calendar week (Sunday to Saturday in the exchange's local time). The sessions are contiguous with no gaps, and any period when... */
  sessions: TradingSession[] | null;
  /** Market holidays and early closes, past and upcoming, sorted by start time. The market is closed from the start time to the end time of each entry. Empty when... */
  holidays: TradingHolidaySchedule[] | null;
}

/** Signature. */
export interface Signature {
  /** The address (public key) of the wallet signing the payload */
  signer: string;
  /** Signature R */
  r: string;
  /** Signature S */
  s: string;
  /** Signature V */
  v: number;
  /** Timestamp after which this signature expires, expressed in unix nanoseconds. Must be capped at 30 days */
  expiration: Timestamp;
  /** Users can randomly generate this value, used as a signature deconflicting key. */
  nonce: number;
  /** Chain ID used in EIP-712 domain. Zero value fallbacks to GRVT Chain ID. */
  chain_id: string;
}

/** SpotBalance. */
export interface SpotBalance {
  /** The currency you hold a spot balance in */
  currency: string;
  /** This currency's balance in this trading account. */
  balance: Decimal;
  /** The index price of this currency. (reported in `USD`) */
  index_price: Decimal;
  /** The entry price of this spot currency. (reported in `USD`) */
  entry_price: Decimal;
  /** The realized PnL of this spot currency. (reported in `USD`) */
  realized_pnl: Decimal;
  /** The unrealized PnL of this spot currency. (reported in `USD`) */
  unrealized_pnl: Decimal;
  /** The available to transfer amount of this spot currency. */
  available_to_transfer: Decimal;
  /** The amount borrowed in this currency, inclusive of accrued interest. */
  borrowed_amount?: Decimal;
}

/** SpotSubAccount. */
export interface SpotSubAccount {
  /** Time at which the event was emitted in unix nanoseconds */
  event_time: Timestamp;
  /** The sub account ID this entry refers to */
  sub_account_id: string;
  /** Total equity of the spot sub account, denominated USD */
  total_equity: Decimal;
  /** The list of spot assets owned by this spot sub account, and their balances */
  spot_balances: SpotBalance[] | null;
}

/** StreamReference. */
export interface StreamReference {
  /** The channel to subscribe to (eg: ticker.s / ticker.d) */
  stream: string;
  /** The list of selectors for the stream */
  selectors: string[] | null;
}

/** SubAccount. */
export interface SubAccount {
  /** Time at which the event was emitted in unix nanoseconds */
  event_time: Timestamp;
  /** The sub account ID this entry refers to */
  sub_account_id: string;
  /** The type of margin algorithm this subaccount uses */
  margin_type: e.MarginType;
  /** The settlement, margin, and reporting currency of this account. */
  settle_currency: string;
  /** The total unrealized PnL of all positions owned by this subaccount, in the quote asset. Decimal string, e.g. "12.5". */
  unrealized_pnl: Decimal;
  /** The notional value of your account if all positions are closed, excluding trading fees (reported in `settle_currency`). */
  total_equity: Decimal;
  /** The `total_equity` required to open positions in the account (reported in `settle_currency`). */
  initial_margin: Decimal;
  /** The `total_equity` required to avoid liquidation of positions in the account (reported in `settle_currency`). */
  maintenance_margin: Decimal;
  /** DEPRECATED: use the per-currency `availableToTransfer` of the quote-currency entry in `spotBalances` instead. */
  available_balance: Decimal;
  /** The list of spot assets owned by this sub account, and their balances */
  spot_balances: SpotBalance[] | null;
  /** The list of positions owned by this sub account */
  positions: Positions[] | null;
  /** The index price of the settle currency. (reported in `USD`) */
  settle_index_price: Decimal;
  /** Whether this sub account is a vault */
  is_vault?: boolean;
  /** Total amount of IM (reported in `settle_currency`) deducted from the vault due to redemptions nearing the end of their redemption period */
  vault_im_additions?: Decimal;
  /** The derisk margin of this sub account */
  derisk_margin: Decimal;
  /** The derisk margin to maintenance margin ratio of this sub account */
  derisk_to_maintenance_margin_ratio: Decimal;
  /** The total equity of this sub account for cross margin */
  total_cross_equity: Decimal;
  /** The unrealized PnL of this sub account for cross margin */
  cross_unrealized_pnl: Decimal;
  /** The mode of the sub account */
  sub_account_mode: e.SubAccountMode;
  /** The margin balance of this sub account for cross margin */
  margin_balance: Decimal;
  /** Whether algo trading is enabled for this sub account */
  algo_trading_enabled: boolean;
}

/** An asset supported for a given wallet type */
export interface SupportedAsset {
  /** The currency ID of the asset */
  asset_id: number;
  /** The readable currency code of the asset */
  asset_code: string;
  /** The number of decimals used for balance representation */
  balance_decimals: number;
  /** The asset cannot be transferred between wallets */
  transfer_disabled: boolean;
}

/** Contains metadata for Take Profit (TP) and Stop Loss (SL) trigger orders. */
export interface TPSLOrderMetadata {
  /** Defines the price type (e.g., index price) that activates a Take Profit (TP) or Stop Loss (SL) order */
  trigger_by: e.TriggerBy;
  /** The Trigger Price of the order. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  trigger_price: Decimal;
  /** If True, the order will close the position when the trigger price is reached */
  close_position: boolean;
  /** If True, the order will be treated as part of a position's split-TP/SL set, subject to aggregate size/count limits. */
  is_split_position: boolean;
}

/** Derived data such as the below, will not be included by default: */
export interface Ticker {
  /** Time at which the event was emitted in unix nanoseconds */
  event_time?: Timestamp;
  /** The readable instrument name: Perpetual: `ETH_USDT_Perp` Future: `BTC_USDT_Fut_20Oct23` Call: `ETH_USDT_Call_20Oct23_2800` Put: `ETH_USDT_Put_20Oct23_2800` */
  instrument?: string;
  /** The mark price of the instrument. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  mark_price?: Decimal;
  /** The index price of the instrument. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  index_price?: Decimal;
  /** The last traded price of the instrument (also close price). Decimal string, e.g. "65000.5"; up to 9 decimals. */
  last_price?: Decimal;
  /** The number of assets traded in the last trade. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  last_size?: Decimal;
  /** The mid price of the instrument. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  mid_price?: Decimal;
  /** The best bid price of the instrument. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  best_bid_price?: Decimal;
  /** The number of assets offered on the best bid price of the instrument. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  best_bid_size?: Decimal;
  /** The best ask price of the instrument. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  best_ask_price?: Decimal;
  /** The number of assets offered on the best ask price of the instrument. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  best_ask_size?: Decimal;
  /** DEPRECATED: To be removed in a future release. Please refer to the field `funding_rate` instead, for the funding rate being applied over... */
  funding_rate_8h_curr?: Decimal;
  /** DEPRECATED: To be removed in a future release. Please refer to the field `funding_rate` instead, for the funding rate being applied over... */
  funding_rate_8h_avg?: Decimal;
  /** The interest rate of the underlying, expressed in centibeeps (1/100th of a basis point) */
  interest_rate?: Decimal;
  /** [Options] The forward price of the option. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  forward_price?: Decimal;
  /** The 24 hour taker buy volume of the instrument. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  buy_volume_24h_b?: Decimal;
  /** The 24 hour taker sell volume of the instrument. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  sell_volume_24h_b?: Decimal;
  /** The 24 hour taker buy volume of the instrument, in the quote asset. Decimal string, e.g. "12.5". */
  buy_volume_24h_q?: Decimal;
  /** The 24 hour taker sell volume of the instrument, in the quote asset. Decimal string, e.g. "12.5". */
  sell_volume_24h_q?: Decimal;
  /** The 24 hour highest traded price of the instrument. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  high_price?: Decimal;
  /** The 24 hour lowest traded price of the instrument. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  low_price?: Decimal;
  /** The 24 hour first traded price of the instrument. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  open_price?: Decimal;
  /** The open interest in the instrument. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  open_interest?: Decimal;
  /** The ratio of accounts that are net long vs net short on this instrument */
  long_short_ratio?: Decimal;
  /** The current indicative funding rate for the active interval, expressed in centibeeps. Absent for stable perps, which have `funding_rate_long_apr_pct` and... */
  funding_rate?: Decimal;
  /** Timestamp in nanoseconds when the current funding interval ends */
  next_funding_time?: Timestamp;
  /** The current status of the instrument */
  status?: e.InstrumentStatus;
  /** The current trading session of the instrument's underlying market */
  session?: e.TradingSessionType;
  /** The long open interest in the instrument. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. Excludes qualified-maker and DMM open interest. */
  long_open_interest?: Decimal;
  /** The short open interest in the instrument. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. Excludes qualified-maker and DMM open interest. */
  short_open_interest?: Decimal;
  /** Stable perps only: the indicative annual rate for retail longs at the next charge, in percent a year (`'-5.5'` = retail longs pay 5.5%; positive = retail... */
  funding_rate_long_apr_pct?: Decimal;
  /** Stable perps only: the indicative annual rate for retail shorts at the next charge, in percent a year (`'-5'` = retail shorts pay 5%; positive = retail... */
  funding_rate_short_apr_pct?: Decimal;
}

/** All private RFQs and Private AXEs will be filtered out from the responses */
export interface Trade {
  /** Time at which the event was emitted in unix nanoseconds */
  event_time: Timestamp;
  /** The readable instrument name: Perpetual: `ETH_USDT_Perp` Future: `BTC_USDT_Fut_20Oct23` Call: `ETH_USDT_Call_20Oct23_2800` Put: `ETH_USDT_Put_20Oct23_2800` */
  instrument: string;
  /** If taker was the buyer on the trade */
  is_taker_buyer: boolean;
  /** The number of assets being traded. Decimal string, e.g. "0.01"; up to the instrument's base_decimals. */
  size: Decimal;
  /** The traded price. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  price: Decimal;
  /** The mark price of the instrument at point of trade. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  mark_price?: Decimal;
  /** The index price of the instrument at point of trade. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  index_price: Decimal;
  /** The interest rate of the underlying at point of trade, expressed in centibeeps (1/100th of a basis point) */
  interest_rate: Decimal;
  /** [Options] The forward price of the option at point of trade. Decimal string, e.g. "65000.5"; up to 9 decimals. */
  forward_price?: Decimal;
  /** A trade identifier, globally unique, and monotonically increasing (not by `1`). */
  trade_id: string;
  /** The venue where the trade occurred */
  venue: e.Venue;
  /** If the trade is a RPI trade */
  is_rpi: boolean;
}

/** TradingHolidaySchedule. */
export interface TradingHolidaySchedule {
  /** Holiday name */
  name: string;
  /** `FULL_DAY`: the market is closed for the whole day. `EARLY_CLOSE`: the market trades as normal until the start time, then is closed until the end time */
  close_type: e.TradingScheduleCloseType;
  /** When the closure begins, as a Unix timestamp in milliseconds. For `FULL_DAY` this is when the closed trading day's session would have opened (the evening... */
  start_time: string;
  /** When the closed or shortened trading day's session would have closed, as a Unix timestamp in milliseconds. The closure covers the start time up to, but not... */
  end_time: string;
}

/** TradingSession. */
export interface TradingSession {
  /** Trading session start time timestamp in milliseconds */
  start_time: string;
  /** Trading session end time timestamp in milliseconds */
  end_time: string;
  /** Trading session type */
  type: e.TradingSessionType;
}

/** TransferHistory. */
export interface TransferHistory {
  /** The transaction ID of the transfer */
  tx_id: string;
  /** The account to transfer from */
  from_account_id: string;
  /** The subaccount to transfer from (0 if transferring from main account) */
  from_sub_account_id: string;
  /** The account to deposit into */
  to_account_id: string;
  /** The subaccount to transfer to (0 if transferring to main account) */
  to_sub_account_id: string;
  /** The token currency to transfer */
  currency: string;
  /** The number of tokens to transfer */
  num_tokens: Decimal;
  /** The signature of the transfer */
  signature: Signature;
  /** The timestamp of the transfer in unix nanoseconds */
  event_time: Timestamp;
  /** The type of transfer */
  transfer_type: e.TransferType;
  /** The metadata of the transfer */
  transfer_metadata: string;
  /** The wallet type of the from account or subaccount */
  from_wallet_type: e.WalletType;
  /** The wallet type of the to account or subaccount */
  to_wallet_type: e.WalletType;
}

/** Contains metadata related to trigger orders, such as Take Profit (TP) or Stop Loss (SL). */
export interface TriggerOrderMetadata {
  /** Type of the trigger order. eg: Take Profit, Stop Loss, etc */
  trigger_type: e.TriggerType;
  /** Contains metadata for Take Profit (TP) and Stop Loss (SL) trigger orders. */
  tpsl: TPSLOrderMetadata;
}

/** Summarizes a vault investment held by a funding account */
export interface VaultInvestment {
  /** The trading account ID of the vault invested in. */
  vault_id: string;
  /** The number of shares held by the investor. */
  num_lp_tokens: Decimal;
  /** The current share price (in USD) of this vault investment. */
  share_price: Decimal;
  /** The USD notional invested in this vault investment. */
  usd_notional_invested: Decimal;
  /** The owner's Funding, trading and reserved vault shares. Absent on older snapshots. */
  share_balances?: VaultShareBalances;
}

/** Vault investor summary information. */
export interface VaultInvestorSummary {
  /** The unique identifier of the vault sub account. */
  sub_account_id: string;
  /** The number of vault LP tokens the investor holds: those in the funding account plus those in every trading account. */
  num_lp_tokens: Decimal;
  /** The average entry price (in USD) of the investor's vault LP tokens: the investor's invested notional divided by numLPTokens. */
  avg_entry_price: Decimal;
  /** The current price (in USD) of the vault LP tokens. */
  current_price: Decimal;
  /** The vault's total equity (in USD). The investor's holding is investorEquity. */
  total_equity: Decimal;
  /** The all-time realized PnL (in USD) that the investor has received from the vault. */
  all_time_realized_pnl: Decimal;
  /** The singleton pending redemption (omitted if none). */
  pending_redemption?: VaultRedemption;
  /** True if the requesting account is authorized to burn tokens on this vault, omitted otherwise. */
  can_burn?: boolean;
  /** The number of the investor's vault LP tokens still within the vault's minimum investment period. */
  num_lp_tokens_locked: Decimal;
  /** The number of vault LP tokens the investor can request to redeem now: those past the minimum investment period, less any pending redemption. */
  num_lp_tokens_redeemable: Decimal;
  /** The investor's vault LP tokens within the minimum investment period, by the time they unlock (earliest first). */
  locked_lots: VaultLpLotView[] | null;
  /** Where the investor's vault LP tokens sit: the funding account and the trading accounts. */
  share_balances: VaultShareBalances;
  /** One entry per trading account holding the vault's LP tokens. Empty when no trading account holds any. */
  trading_balances: VaultShareTradingBalance[] | null;
  /** The current valuation (in USD) of all the investor's vault LP tokens: numLPTokens times currentPrice. */
  investor_equity: Decimal;
  /** The investor's unrealized PnL (in USD): investorEquity less the investor's invested notional. */
  unrealized_pnl: Decimal;
}

/** Vault LP tokens minted together that unlock at the same time. */
export interface VaultLpLotView {
  /** Time in unix nanoseconds from which these LP tokens can be redeemed. */
  unlock_time: Timestamp;
  /** The number of LP tokens in the lot. */
  num_lp_tokens: Decimal;
}

/** Vault redemption information. */
export interface VaultRedemption {
  /** The number of LP Tokens requested for redemption. */
  num_lp_tokens: Decimal;
  /** The valuation (in USD) of the redemption request. */
  request_valuation: Decimal;
  /** Set by the server. Time at which the redemption request was received by GRVT in unix nanoseconds */
  request_time: Timestamp;
  /** Set by the server. Time in unix nanoseconds, beyond which the request will be force-redeemed. */
  max_redemption_period_timestamp: Timestamp;
  /** Omitted for redemption requests to non-cross exchange vaults. True if cancellation is blocked within the CEV allocation allowance for the user's current tier... */
  cancel_blocked?: boolean;
  /** The currency the request pays into the investor's funding account: the vault's investment currency, unless the request converts. */
  to_currency: string;
  /** The signed rate the request is paid at, `to_currency` per unit of the vault's investment currency. 1 when the request does not convert. */
  exchange_rate: Decimal;
}

